//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			Analog Input Advanced                                                                                                                                                                                                                                                                         
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE					SIGN								DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2025-04-22			William Veim					Initial release    
//	1.0.1				2025-05-02			Ruben Byman					Fixed state control signal value out of range and added function to ignore in case of loop break. Added input to turn on/off loop break check
// 1.0.2				2025-06-24			Jan Magne Dybvik			Added configuration for Alarm SMS Process value (Cfg_AlarmSMS_SignificantDigits and Cfg_AlarmSMS_UseUnitPrefix)
// 1.0.3				2025-06-24			Jan Magne Dybvik  			Added configuration of ProcessUnit and added assigment of unit to SCADA structure
//	1.2.0				2025-03-19			William Veim					Removed input for SMS process value 
//	1.2.1				2026-05-29			Ruben Byman					Bugfix scaling, removed raw value min/max
//
//===============================================================================================================================
//
//		FUNKSJONALITET:
//		*Analog input (signal value) 
//		*Scaling of raw value to signal value
//		*Excecution of analog input logic
//
//===============================================================================================================================

 (*************************************************************************
 *	INITIALIZE VARIABELS
 *************************************************************************)

Ext_AnalogValue.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA

IF  NOT Ext_AnalogValue.INT_Data.Initialise THEN
	
	//Common parameters are initialised in logic block
	
	//State config
	Ext_AnalogValue.EXT_Engineering.StateCfg_10.Cfg_Quality:=3; //Signal value out of range = High
	Ext_AnalogValue.EXT_Engineering.StateCfg_10.Cfg_Alarm:=TRUE; //Output module fault = Alarm
	Ext_AnalogValue.EXT_Engineering.StateCfg_11.Cfg_Quality:=4; //Loop break = Critical
	Ext_AnalogValue.EXT_Engineering.StateCfg_11.Cfg_Alarm:=TRUE; //Loop break = Alarm
	
	//Initialise set true in logic block
	
END_IF;

(*************************************************************************
 *	BLOCK SPESIFIC PARAMETERS
 *************************************************************************)
 
FB_AnalogInput_Logic.Cfg_ValueType:=FALSE; //INPUT VALUE TO LOGIC BLOCK IS SIGNAL VALUE
FB_AnalogInput_Logic.Cfg_CalibrationEnable:=	Cfg_CalibrationEnable;

Wrk_SignalValue_Unit:= 			Cfg_SignalValue_Unit;
Wrk_SignalValue_Y0:=				Cfg_SignalValue_Y0;
Wrk_SignalValue_Y1:=				Cfg_SignalValue_Y1;
Wrk_SignalValue_Min:= 			Cfg_SignalValue_Min;
Wrk_SignalValue_Max:= 			Cfg_SignalValue_Maks;
Wrk_RawValue_X0:= 				Cfg_RawValue_X0;
Wrk_RawValue_X1:= 				Cfg_RawValue_X1;
Wrk_RawValueLoopBreak := 	Cfg_RawValue_LoopBreak;

(*************************************************************************
 *	UPDATE INPUT PARAMETERS
 *************************************************************************)

FB_AnalogInput_Logic.Inp_AlmSuppress:=				Inp_AlmSuppress;
FB_AnalogInput_Logic.Inp_AlmSuppressDesc:=		Inp_AlmSuppressDesc;
FB_AnalogInput_Logic.Inp_ModuleFault:=				Inp_ModuleFault;

IF NOT Cfg_LoopBreak_InUse OR (Inp_RawValue <> Wrk_RawValueLoopBreak) THEN
	FB_AnalogInput_Logic.Inp_Value:=							ScaleTrans(SclIn:=Inp_RawValue, 
																											X0:=Wrk_RawValue_X0, 
																											Y0:=Wrk_SignalValue_Y0, 
																											X1:=Wrk_RawValue_X1, 
																											Y1:=Wrk_SignalValue_Y1);
																									
	FB_AnalogInput_Logic.Inp_Value:=							LIMIT(MN:= Wrk_SignalValue_Min, 
																									In:=FB_AnalogInput_Logic.Inp_Value, 
																									MX:=Wrk_SignalValue_Max);
ELSE
	FB_AnalogInput_Logic.Inp_Value:=0;
END_IF;

(*************************************************************************
 *	UPDATE CONFIG PARAMETERS
 *************************************************************************)
 
FB_AnalogInput_Logic.Cfg_SignalValue_Y0:=							Wrk_SignalValue_Y0;
FB_AnalogInput_Logic.Cfg_SignalValue_Y1:=							Wrk_SignalValue_Y1;
FB_AnalogInput_Logic.Cfg_SignalValue_Unit:=						Wrk_SignalValue_Unit;
FB_AnalogInput_Logic.Cfg_ControlCabinet:=							Cfg_ConnCabinet;
FB_AnalogInput_Logic.Cfg_ControllerTAG:=							Cfg_ControllerName;
FB_AnalogInput_Logic.Cfg_ProcessTAG:=								Cfg_ProcessTAG;
FB_AnalogInput_Logic.Cfg_ProcessValue_Unit := 					Cfg_ProcessValue_Unit;

(*************************************************************************
 *	STATISTICS
 * (Asuming sensor has been changed, if loop break over a period)
 *************************************************************************)

TON_LoopBreak(In:=Wrk_LoopBreak AND NOT Inp_ModuleFault, PT:=TIME#2h);

FB_AnalogInput_Logic.Inp_RstOperatingTime:=TON_LoopBreak.Q;

(*************************************************************************
 *	UPDATING STATE CONTROL PARAMTERS
 *************************************************************************)

 //STATE 1 - Locked to "Critical high limit"
 //STATE 2 - Locked to "Pre high limit"
 //STATE 3 - Locked to "Pre low limit"
 //STATE 4 - Locked to "Critical low limit"
 //STATE 5 - Locked to "Process value out of range"
 //STATE 6 - Locked to "Input module fault"
 //STATE 7 - Locked to "Value stuck"
 //STATE 8 - Locked to "Calibration fault"
 //STATE 9 - Locked to "Unstable value"
 
Wrk_LoopBreak := Inp_RawValue = Wrk_RawValueLoopBreak AND Cfg_LoopBreak_InUse;
TON_SignalValueFault(In:=(FB_AnalogInput_Logic.Inp_Value < (Wrk_SignalValue_Y0 * 0.99) OR FB_AnalogInput_Logic.Inp_Value > (Wrk_SignalValue_Y1 * 1.01)) AND NOT Wrk_LoopBreak, //Ignores if loop break
									PT:=TIME#10s);

Wrk_SignalValueFault:=TON_SignalValueFault.Q;
 
FB_AnalogInput_Logic.Cfg_State10_InUse:= 	TRUE;
FB_AnalogInput_Logic.Inp_State10_Desc:=		'Signal value out of range';
FB_AnalogInput_Logic.Inp_State10_State:= 	Wrk_SignalValueFault;

FB_AnalogInput_Logic.Cfg_State11_InUse:= 	Cfg_LoopBreak_InUse;
FB_AnalogInput_Logic.Inp_State11_Desc:=		'Loop break';
FB_AnalogInput_Logic.Inp_State11_State:=		Wrk_LoopBreak;

FB_AnalogInput_Logic.Cfg_State12_InUse:= 	FALSE;
FB_AnalogInput_Logic.Inp_State12_Desc:=	'	NOT IN USE';
FB_AnalogInput_Logic.Inp_State12_State:=		FALSE;

(*************************************************************************
 *	EXCECUTING LOGICK BLOCK
 *************************************************************************)
 
FB_AnalogInput_Logic(ENS:=TRUE, 
										Ext_AnalogValue:=	Ext_AnalogValue, 
										Int_Alarm:=				Int_Alarm); 

(*************************************************************************
 *	UPDATING FB OUTPUT
 *************************************************************************)
 
Sts_Alarm:= 								FB_AnalogInput_Logic.Sts_AlarmTriggered;
Out_ProcessValue:= 				Ext_AnalogValue.EXT_Operator.ProcessValue;
Out_ProcessValue_Percent := 	Ext_AnalogValue.EXT_Operator.ProcessValue_Percent;
